function validate<T>(value: unknown, schema: Schema): T {
  if (!matches(value, schema)) throw new Error('local_simulation_wire_contract_invalid')
  return value as T
}

// A serialized tag, copied object or browser input cannot mint this capability.
declare const localScope: unique symbol
export type LocalSimulationContext = Readonly<{ readonly [localScope]: true }>
type RequestClient = Awaited<ReturnType<typeof createSupabaseServerClient>>
type Authority = { client: RequestClient; actorId: string; basis: BasisResponse; state: 'minted'|'running' }
const authority = new WeakMap<LocalSimulationContext, Authority>()
async function verifiedClient(): Promise<{ client: RequestClient; actorId: string }> {
  const client = await createSupabaseServerClient()
  const { data, error } = await client.auth.getUser()
  if (error || !data.user?.id) throw new Error('local_simulation_authenticated_actor_required')
  return { client, actorId: data.user.id }
}
async function invoke<T>(client: RequestClient, name: string, args: unknown): Promise<T> {
  const schema = rpcSchemas[name]
  if (!schema || ['gridex_assert_external_delivery_allowed_v1','gridex_assert_invoice_external_delivery_allowed_v1'].includes(name)) throw new Error('local_simulation_command_not_allowed')
  validate(args, schema.request)
  recordLocalImportDiagnostic({stage:'SDK_RPC',event:'rpc_start',operation:name})
  const response = await client.rpc(name, args)
  recordLocalImportDiagnostic({stage:'SDK_RPC',event:'rpc_result',operation:name,status:response.status,statusText:response.statusText,error:response.error})
  const { data, error } = response
  if (error) throw error
  return validate<T>(data, schema.response)
}
export async function issueLocalSimulation(request: IssueRequest): Promise<IssueResponse> {
  const { client, actorId } = await verifiedClient()
  const result = await invoke<IssueResponse>(client, 'gridex_issue_local_simulation_run_v1', { p_command: request })
  if (result.companyId !== request.companyId || result.issuerActorId !== actorId) throw new Error('local_simulation_scope_mismatch')
  return result
}
export async function receiveLocalSimulationSource(request: ReceiveRequest): Promise<ReceiveResponse> {
  if(typeof request.rawEdifact!=='string' || Buffer.byteLength(request.rawEdifact,'utf8')>2097152) throw new Error('local_simulation_raw_source_too_large')
  const { client } = await verifiedClient()
  const result = await invoke<ReceiveResponse>(client, 'gridex_receive_local_simulation_source_v1', { p_command: request })
  if(result.admissionId!==request.admissionId || result.sourceSlotKey!==request.sourceSlotKey
    || result.rawSha256!==createHash('sha256').update(request.rawEdifact,'utf8').digest('hex')) throw new Error('local_simulation_scope_mismatch')
  return result
}
export async function prepareLocalSimulationContract(request: PrepareRequest): Promise<PrepareResponse> {
  const { client } = await verifiedClient()
  const result = await invoke<PrepareResponse>(client, 'gridex_prepare_local_simulation_contract_v1', { p_command: request })
  if(result.admissionId!==request.admissionId || result.companyId!==request.companyId || result.manifestSha256!==request.expectedManifestSha256
    || result.documentSha256!==createHash('sha256').update(result.documentText,'utf8').digest('hex')) throw new Error('local_simulation_scope_mismatch')
  return result
}
export async function attestLocalSimulationContract(admissionId: string, contractId: string, documentSha256: string): Promise<AttestResponse> {
  const { client,actorId } = await verifiedClient()
  const result = await invoke<AttestResponse>(client, 'gridex_attest_local_simulation_contract_v1', { p_admission_id: admissionId, p_contract_id: contractId, p_document_sha256: documentSha256 })
  if(result.admissionId!==admissionId || result.contractId!==contractId || result.actorId!==actorId || result.documentSha256!==documentSha256) throw new Error('local_simulation_scope_mismatch')
  return result
}
export async function revokeLocalSimulation(admissionId: string, reason: string): Promise<RevokeResponse> {
  const { client,actorId } = await verifiedClient()
  const result = await invoke<RevokeResponse>(client, 'gridex_revoke_local_simulation_run_v1', { p_admission_id: admissionId, p_reason: reason })
  if(result.admissionId!==admissionId || result.actorId!==actorId) throw new Error('local_simulation_scope_mismatch')
  return result
}
export async function bindLocalSimulation(input: { admissionId: string; companyId: string; customerId: string; contractId: string; sourceSha256: string }): Promise<LocalSimulationContext> {
  const { client, actorId } = await verifiedClient()
  const basis = await invoke<BasisResponse>(client, 'gridex_assert_local_simulation_basis_v1', {
    p_admission_id: input.admissionId, p_company_id: input.companyId, p_customer_id: input.customerId,
    p_contract_id: input.contractId, p_source_sha256: input.sourceSha256, p_environment: 'test',
  })
  if (basis.admissionId !== input.admissionId || basis.companyId !== input.companyId || basis.customerId !== input.customerId
    || basis.contractId !== input.contractId || basis.ids.customerId !== input.customerId || basis.ids.contractId !== input.contractId || basis.sourceSha256 !== input.sourceSha256
    || Date.parse(basis.expiresAt) <= Date.now()) throw new Error('local_simulation_scope_mismatch')
  const context = Object.freeze({}) as LocalSimulationContext
  authority.set(context, { client, actorId, basis, state:'minted' })
  return context
}
export function requireLocalSimulation(context: LocalSimulationContext, scope: { companyId: string; customerId?: string; contractId?: string; sourceSha256?: string }): Readonly<BasisResponse> {
  const entry = authority.get(context)
  if (!entry || entry.basis.companyId !== scope.companyId || (scope.customerId !== undefined && entry.basis.customerId !== scope.customerId)
    || (scope.contractId !== undefined && entry.basis.contractId !== scope.contractId)
    || (scope.sourceSha256 !== undefined && entry.basis.sourceSha256 !== scope.sourceSha256)
    || Date.parse(entry.basis.expiresAt) <= Date.now()) throw new Error('local_simulation_context_invalid')
  return structuredClone(entry.basis)
}
type CommandResults = { ack_capture: AckResult; meter_gate: MeterGateResult; underlay_store_batch: UnderlayStoreResult; pricing_persist: PricingPersistResult; pricing_lock: PricingLockResult; invoice_draft_prepare: InvoicePrepareResult }
export async function executeLocalSimulation<C extends keyof CommandResults>(context: LocalSimulationContext, command: C, payload: Record<string, unknown>, idempotencyKey: string): Promise<Omit<CommandReceipt, 'result'> & { result: CommandResults[C] }> {
  const entry = authority.get(context)
  if (!entry) throw new Error('local_simulation_context_invalid')
  const frame=requestScope.getStore()
  if(!frame || !frame.active || frame.context!==context || entry.state!=='running') throw new Error('local_simulation_request_scope_closed')
  const basis = requireLocalSimulation(context, { companyId: entry.basis.companyId })
  const { data, error } = await entry.client.auth.getUser()
  if (error || data.user?.id !== entry.actorId) throw new Error('local_simulation_authenticated_actor_required')
  if(!frame.active || authority.get(context)!==entry || requestScope.getStore()!==frame) throw new Error('local_simulation_request_scope_closed')
  const result = await invoke<CommandReceipt>(entry.client, 'gridex_execute_local_simulation_command_v1', { p_command: {
    version: 1, admissionId: basis.admissionId, companyId: basis.companyId, command,
    expectedBasisSha256: basis.basisSha256, inputSha256: null, idempotencyKey, payload,
  } })
  if (result.actorId !== entry.actorId || result.admissionId !== basis.admissionId || result.companyId !== basis.companyId
    || result.command !== command || result.basisSha256 !== basis.basisSha256) throw new Error('local_simulation_scope_mismatch')
  return result as Omit<CommandReceipt, 'result'> & { result: CommandResults[C] }
}

// Only the awaited raw-import pipeline inherits this request capability. The
// store holds no source-id cache and never manufactures authority from inputs.
const requestScope = new AsyncLocalStorage<{context:LocalSimulationContext;active:boolean}>()
export async function withLocalSimulation<T>(context: LocalSimulationContext, scope: { companyId: string; customerId: string; contractId: string; sourceSha256: string }, callback: () => Promise<T>): Promise<T> {
  requireLocalSimulation(context, scope)
  const entry=authority.get(context)
  if(!entry || entry.state!=='minted') throw new Error('local_simulation_context_invalid')
  entry.state='running'
  const frame={context,active:true}
  return requestScope.run(frame,async()=>{try{return await callback()}finally{frame.active=false;authority.delete(context)}})
}
export function currentLocalSimulation(scope: { companyId: string; customerId?: string; contractId?: string; sourceSha256?: string }): LocalSimulationContext | null {
  const frame = requestScope.getStore()
  if (!frame) return null
  if(!frame.active) throw new Error('local_simulation_request_scope_closed')
  requireLocalSimulation(frame.context, scope)
  return frame.context
}
export function readLocalIssuerIdentity(value: unknown): LocalIssuerIdentityRead {
  return validate<LocalIssuerIdentityRead>(value, definitions.LocalIssuerIdentityRead)
}
export function requireLocalSimulationActor(context:LocalSimulationContext,actorId:string):void {
  const entry=authority.get(context)
  if(!entry || entry.actorId!==actorId) throw new Error('local_simulation_actor_mismatch')
  requireLocalSimulation(context,{companyId:entry.basis.companyId})
}
